update pages set contenu = '{"sections":[{"type":"heros","h1":"Maintenance industrielle à Troyes et dans l''Aube","mecanisme":"La bonneterie troyenne a laissé deux héritages. Des ateliers de textile technique qui font encore tourner des métiers à tricoter. Et des centres de marques, qui ont attiré les entrepôts du e-commerce autour de l''agglomération. Ajoutez les malteries de Nogent-sur-Seine, et l''Aube travaille sur trois calendriers différents. Nos techniciens itinérants couvrent le département et se déplacent partout en France.","cta":"Demander une intervention à Troyes","telephone":"04 78 33 72 05","phraseDelai":"Nous vous rappelons dans l''heure, du lundi au vendredi de 8h00 à 18h30. L''astreinte 24/24 et 7/7 couvre les nuits, les week-ends et les jours fériés."},{"type":"chiffres","chiffres":[{"valeur":"+ 120","libelle":"clients industriels accompagnés, dont plus de 80 réguliers"},{"valeur":"10 %","libelle":"des candidats retenus, entretien technique et comportemental"},{"valeur":"4","libelle":"agences, Lyon (siège), Montréal, Dubaï, Madrid, et des techniciens mobiles partout en France"}]},{"type":"probleme","punchline":"Une ligne d''agroalimentaire décroche un vendredi soir dans l''Aube. C''est tout le week-end de production qui saute, et lundi la commande est déjà en retard.","puces":[{"accroche":"Le pic de commandes ne se négocie pas.","texte":"Sur les entrepôts de la couronne troyenne, un trieur à l''arrêt en pleine vague bloque des milliers d''expéditions."},{"accroche":"Les machines textiles sont rares et anciennes.","texte":"Peu de gens savent encore les régler, et les remplacer coûte plus que les fiabiliser."},{"accroche":"Le continu ne laisse pas de fenêtre.","texte":"Malteries et lignes de conditionnement tournent sans interruption : le préventif se planifie des mois à l''avance."},{"accroche":"Une presse à injecter mal entretenue produit du rebut.","texte":"En plasturgie, la dérive se voit dans la pièce avant de se voir dans l''alarme."},{"accroche":"Un départ, et l''atelier perd sa mémoire.","texte":"Le technicien qui connaissait le parc emporte l''historique avec lui."}]},{"type":"offre","lignes":[{"prestation":"**Préventif planifié** sur vos heures de fonctionnement réelles, resserré avant les pics de commandes.","benefice":"Les révisions tombent avant la charge, jamais pendant la vague."},{"prestation":"**Dépannage sur site** avec recherche de cause racine, du moteur à l''armoire électrique.","benefice":"Le même défaut ne revient pas sous un autre nom le mois suivant."},{"prestation":"**Machines anciennes et parcs hétérogènes** : réglage, remise en état, rétrofit d''automate et de variation de vitesse.","benefice":"Vous prolongez un outil amorti au lieu d''investir dans du neuf."},{"prestation":"**Convoyeurs, trieurs et quais** des entrepôts : voir la [maintenance équipements logistiques](/secteurs/logistique/).","benefice":"Un seul contrat du quai de réception au quai d''expédition."},{"prestation":"**Froid industriel et utilités** : échangeurs, réseaux d''air comprimé, réseaux d''eau, chasse aux fuites.","benefice":"La dérive énergétique se corrige avant de peser sur la facture."},{"prestation":"**Astreinte 24/24 et 7/7 en option**, mobilisation de techniciens mobiles partout en France.","benefice":"Une panne du vendredi soir ne coûte pas un week-end de production."},{"prestation":"**Technicien en [Résidence](/offres/residence/)** intégré à votre équipe, prise de poste en 2 à 3 semaines.","benefice":"Le poste vacant cesse d''être une fragilité, remplacement assuré."},{"prestation":"**Contrat [Zéro arrêt](/offres/zero-arret/)** : visites planifiées, priorité en cas de panne, diagnostic gratuit au départ.","benefice":"Le préventif entre au planning au lieu de sauter dès que la charge monte."}]},{"type":"deroule","etapes":[{"titre":"Premier contact","texte":"vous décrivez la panne ou le besoin. Un chargé d''affaires rappelle dans l''heure aux horaires ouvrés."},{"titre":"Qualification","texte":"machines, accès au site, habilitations, contraintes d''hygiène et de cadence. Tout se note avant le chiffrage."},{"titre":"Devis écrit","texte":"périmètre, créneaux, matériel, conditions horaires. L''exceptionnel se chiffre en amont."},{"titre":"Intervention","texte":"accueil sécurité, plan de prévention, consignation, diagnostic, réparation, redémarrage sécurisé."},{"titre":"Compte rendu","texte":"opérations, temps passé, pièces à prévoir, préconisations, versés dans votre GMAO."},{"titre":"Suivi","texte":"sur contrat, revue de la disponibilité et de la récurrence, équipement par équipement."}]},{"type":"garanties","puces":[{"accroche":"Le profil vous est présenté avant l''intervention.","texte":"Entretien technique et comportemental, 10 % des candidats retenus, résultats d''évaluation partagés."},{"accroche":"L''historique machine reste chez vous.","texte":"Comptes rendus versés dans votre outil, préconisations chiffrées. Vous ne dépendez pas de la mémoire d''un homme, ni de la nôtre."},{"accroche":"Un périmètre et une sortie écrits.","texte":"Inclus, exclu, conditions d''astreinte, conditions d''arrêt du contrat."}]},{"type":"cta","question":"Besoin de tenir vos lignes pendant le prochain pic de commandes ?","bouton":"Demander une intervention à Troyes","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."},{"type":"preuves","preuves":[{"titre":"6 techniciens polyvalents en permanence sur un contrat de préventif annuel e-commerce","texte":", reprise complète en un mois","lienLibelle":"Étude de cas VEEPEE : sites de Lyon","lienHref":"/preuves/veepee-sites-lyon/"},{"titre":"10 à 20 techniciens une semaine sur deux, par créneaux de 8 heures, sur un centre logistique en continu","texte":", depuis septembre 2022","lienLibelle":"Étude de cas AMAZON : maintien d''un centre logistique","lienHref":"/preuves/amazon-centre-logistique/"},{"titre":"2 techniciens intégrés en 3x8 sur des lignes agroalimentaires à haute cadence","texte":", liquides et conditionnement poudre","lienLibelle":"Étude de cas DANONE : lignes de production","lienHref":"/preuves/danone-lignes-de-production/"},{"titre":"Un technicien polyvalent sur un parc machines hétérogène en papier et emballage","texte":", 2025 à 2026","lienLibelle":"Étude de cas VPK : maintenance de site","lienHref":"/preuves/vpk/"}]},{"type":"objections","questions":[{"question":"Intervenez-vous vraiment à Troyes, alors que votre siège est à Lyon ?","reponse":"Oui. Nous n''avons pas d''agence dans l''Aube et nous ne l''inventons pas : nos techniciens se déplacent partout en France et interviennent sur site. Votre demande est rappelée dans l''heure aux horaires ouvrés, et vous savez dès le premier appel si le besoin est tenable."},{"question":"Quelles communes couvrez-vous ?","reponse":"Troyes, Sainte-Savine, La Chapelle-Saint-Luc, Rosières-près-Troyes et les zones d''activité de la couronne, ainsi que Nogent-sur-Seine. Au-delà, le réseau national prend le relais."},{"question":"Nos machines textiles sont spécifiques. Vous savez intervenir dessus ?","reponse":"Le premier passage sert d''état des lieux. Mécanique fine, réglage, variation de vitesse et rétrofit d''automate se traitent machine par machine. Si une spécialité manque, le chargé d''affaires le dit au lieu d''envoyer quelqu''un au hasard."},{"question":"Que se passe-t-il en cas de panne un vendredi soir ?","reponse":"L''astreinte 24/24 et 7/7 prend l''appel et mobilise un technicien. Le circuit d''appel et l''ordre des priorités sont écrits au devis, site par site, avant la première urgence."},{"question":"Combien coûte un contrat de maintenance ?","reponse":"L''offre Zéro arrêt fonctionne en abonnement, trois niveaux de couverture, sur devis, engagement type 6 mois renouvelable, diagnostic gratuit au départ."},{"question":"Travaillez-vous dans notre GMAO ?","reponse":"Oui. Chaque intervention y est saisie : temps passé, pièces, préconisations, historique par machine. Pas de système parallèle, pas de double saisie. Vos données vous appartiennent."}]},{"type":"ctaFinal","question":"Besoin d''un partenaire technique avant la prochaine montée en charge ?","bouton":"Demander une intervention à Troyes","rappel":"ou appelez le 04 78 33 72 05, rappel dans l''heure aux horaires ouvrés."}]}'::jsonb where path = '/implantations/maintenance-industrielle-troyes/';
